const routes = [
  ['staff-management','All Staff',Users],['staff-management/add','Add Staff',Plus],['staff-management/roles','Roles & Permissions',ShieldCheck],['staff-management/logs','Activity Logs',Activity],
  ['dashboard','Overview',Activity],['support-center','Support Center',MessageCircle],['users','Users',Users],['creators','Creators',Users],['matching','Matching',Activity],['calls','Calls',Video],['video-sessions','Video sessions',Video],['story-moderation','Story moderation',ShieldCheck],
  ['wallets','Wallets',Wallet],['transactions','Transactions',Coins],['coin-packages','Coin packages',Coins],['gifts','Virtual Gifts',Sparkles],['payments','Payments',Wallet],['payouts','Payouts',Wallet],['moderation','Moderation',ShieldCheck],
  ['analytics','Analytics',Activity],['website-management/pages','Pages',Monitor],['website-management/media','Media Library',Image],['website-management/navigation','Navigation & Footer',Link2],['website-management/seo','SEO Settings',FileSearch],['settings/general','General settings',ShieldCheck],['settings/appearance','Appearance & Themes',Palette],['settings/economy','Economy settings',Coins],['settings/payments','Payment settings',ShieldCheck],['settings/authentication','Authentication',ShieldCheck],['settings/sounds','Sound Management',Bell],['audit-logs','Audit log',Activity],
] as const;
const titles:Record<string,[string,string]>={'staff-management':['Staff Management','Manage staff access, roles, invitations and account activity.'],'staff-management/add':['Add Staff','Invite an administrator or support team member.'],'staff-management/roles':['Roles & Permissions','Review access scopes enforced by the admin API.'],'staff-management/logs':['Activity Logs','Review recorded staff and administrator actions.'],dashboard:['Overview','Platform activity and current operating totals.'],'support-center':['Support Center','Customer conversations, approved FAQs, agents and support settings.'],users:['User management','Registered accounts and guest sessions.'],creators:['Creators','Creator accounts, approval status, and availability.'],matching:['Matching','Current availability and active call volume.'],calls:['Calls','Recent one-to-one video calls and their lifecycle.'],'video-sessions':['Video sessions','Call lifecycle and active session controls.'],'story-moderation':['Story moderation','Review reported stories and remove content that violates community rules.'],wallets:['Wallets','Balances returned by member wallet records.'],transactions:['Transactions','Immutable coin and credit ledger entries.'], 'coin-packages':['Coin packages','Manage the packages available in the wallet store.'],gifts:['Virtual Gifts','Manage the live gift catalog, categories, animations, and coin prices.'],payments:['Payments','Payment records returned by the application database.'],payouts:['Payouts','Creator withdrawal requests and processing state.'],moderation:['Moderation','Open safety reports and their reported accounts.'],reports:['Reports','Safety reports submitted by platform members.'],models:['Creators','Creator accounts, approval status, and availability.'],analytics:['Analytics','User growth, revenue, and platform totals.'],'website-management/pages':['Website Management','Edit public page content, preview drafts, and publish updates.'],'website-management/media':['Website Management · Media Library','Manage reusable public website images.'],'website-management/navigation':['Website Management · Navigation & Footer','Manage public navigation, footer links, and brand copy.'],'website-management/seo':['Website Management · SEO Settings','Manage published homepage SEO metadata.'],'settings/general':['General settings','Platform identity and basic operational settings.'],'settings/appearance':['Appearance & Themes','Manage the application and administration color systems.'],'settings/economy':['Economy settings','Call pricing, creator share, rewards and withdrawal threshold.'],'settings/payments':['Payment settings','Safe status checks for payment integrations.'],'settings/authentication':['Authentication settings','Configure Google and Apple sign-in providers.'],'settings/sounds':['Sound Management','Configure event audio and user sound preferences.'],'audit-logs':['Audit log','Recorded administrator changes.']};
const cash=(n:number,currency='USD')=>{try{return new Intl.NumberFormat(undefined,{style:'currency',currency}).format(Number(n||0)/100)}catch{return `${currency} ${(Number(n||0)/100).toFixed(2)}`}};
export default function AdminSection({section}:{section:string}){
 const toast=useToast();
 const dialog=useDialog();
 const [data,setData]=useState<Data|null>(null),[error,setError]=useState(''),[busy,setBusy]=useState(false),[collapsed,setCollapsed]=useState(false),[mobileOpen,setMobileOpen]=useState(false),[quickOpen,setQuickOpen]=useState(false),[profileOpen,setProfileOpen]=useState(false),[toolbarProfileOpen,setToolbarProfileOpen]=useState(false);
 const load=async()=>{setBusy(true);try{const userId=section.startsWith('users/')?section.slice('users/'.length):'';const endpoint=section==='support-center'?'/api/admin/support':section.startsWith('staff-management')?`/api/admin/staff${section==='staff-management/logs'?'?view=logs':''}`:section.startsWith('website-management/')?'/api/admin/cms':userId?`/api/admin/users/${encodeURIComponent(userId)}`:`/api/admin?section=${encodeURIComponent(section)}`;const r=await fetch(endpoint,{cache:'no-store',signal:AbortSignal.timeout(15_000)});const j=await readApiJson(r,'Administrator request failed.');if(!r.ok)throw new Error(j.error||'Unable to load administrator data');setData(j);setError('')}catch(e){setError(e instanceof DOMException&&e.name==='TimeoutError'?'This page took too long to respond. Retry in a moment.':e instanceof Error?e.message:'Could not load administrator data')}finally{setBusy(false)}};
 useEffect(()=>{void load();const refresh=(event:Event)=>{const complete=(event as CustomEvent<{complete?:()=>void}>).detail?.complete;void load().finally(()=>complete?.())};window.addEventListener('velora-admin-refresh',refresh);if(section!=='dashboard')return()=>window.removeEventListener('velora-admin-refresh',refresh);const timer=window.setInterval(()=>{if(document.visibilityState==='visible')void load()},30_000);return()=>{window.clearInterval(timer);window.removeEventListener('velora-admin-refresh',refresh)}},[section]);
 const [title,description]=section.startsWith('users/')?['User details','Account profile, wallet, calls, safety reports and audit trail.']:(titles[section]||['Admin page','Administrator data']);
 const users=useMemo(()=>{const source=Array.isArray(data?.users)?data.users:[];return source.filter((u:any)=>section==='creators'||section==='models'?u.accountType==='CREATOR':section==='users'?u.role!=='ADMIN'&&u.accountType!=='CREATOR':true)},[data,section]);
 async function action(payload:unknown):Promise<boolean>{const r=await fetch('/api/admin',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const j=await readApiJson(r,'Administrator request failed.').catch(()=>({}));if(!r.ok){setError(j.error||'Action failed');toast.error('Unable to complete action',j.error||'Please try again.');return false}await load();if((payload as any)?.action==='settings'){const values=(payload as any).values;document.dispatchEvent(new CustomEvent('velora-platform-settings-change',{detail:{siteName:values?.siteName,logoUrl:values?.logoUrl}}))}toast.success('Changes saved','The requested admin action is complete.');return true}
 const actionWithoutResult=async(payload:unknown):Promise<void>=>{await action(payload)};
 async function logout(){
  try {
   const response = await fetch('/api/admin/auth/logout', { method:'POST' });
   if (!response.ok) throw new Error('Could not sign out. Please try again.');
   location.replace('/admin/login');
  } catch {
   toast.error('Could not sign out', 'Please try again.');
  }
 }
 if(error&&!data)return <main className="admin-v2 admin-frame"><div className="admin-frame-shell admin-frame-error"><nav><b>flirra. <small>ADMIN</small></b><a href="/"><ArrowLeft size={15}/> Public site</a></nav><section className="admin-v2-error"><ShieldCheck/><h1>Couldn’t load this page</h1><p>{error}</p><button className="admin-v2-refresh" onClick={()=>void load()} disabled={busy}><RefreshCw size={15}/>{busy?'Retrying…':'Try again'}</button><a href="/admin/login?next=%2Fadmin%2Fdashboard">Secure sign in</a></section></div></main>;
 if(!data)return <main className="admin-v2 admin-frame"><div className="admin-frame-shell admin-frame-loading"><div className="admin-v2-loading"><VeloraLoader label="Loading platform data"/><TableSkeleton rows={5} columns={4}/></div></div></main>;
 const stats=data.stats||{};
 const groups=[['WORKSPACE',['dashboard','users','creators']],['STAFF',['staff-management','staff-management/add','staff-management/roles','staff-management/logs']],['SUPPORT',['support-center']],['OPERATIONS',['matching','calls','video-sessions','moderation','story-moderation']],['FINANCE',['wallets','transactions','coin-packages','gifts','payments','payouts']],['INSIGHTS',['analytics','audit-logs']],['WEBSITE MANAGEMENT',['website-management/pages','website-management/media','website-management/navigation','website-management/seo']],['CONFIGURATION',['settings/general','settings/appearance','settings/economy','settings/payments','settings/authentication','settings/sounds']]] as const;
 const nav=groups.map(([group,paths])=><div className="admin-v2-nav-group" key={group}><small>{group}</small>{routes.filter(([path])=>(paths as readonly string[]).includes(path)).map(([path,label,Icon])=><a key={path} className={section===path?'active':''} href={`/admin/${path}`} title={collapsed?label:undefined} onClick={()=>setMobileOpen(false)}><Icon size={17}/><span>{label}</span></a>)}</div>);
 const quickLinks=[['users','Add or review members',Users],['coin-packages','Manage coin packages',Coins],['moderation','Review safety reports',ShieldCheck]] as const;
 return <main className="admin-v2 admin-frame"><div className={`admin-frame-shell${collapsed?' is-collapsed':''}`}>
   <aside className={`admin-v2-sidebar${mobileOpen?' is-mobile-open':''}`}>
    <div className="admin-v2-brand-row"><a className="admin-v2-brand" href="/admin/dashboard"><span>{data.settings?.logoUrl?<img src={data.settings.logoUrl} alt=""/>:<ShieldCheck size={17}/>}</span><b>{data.settings?.siteName||'Velora'}</b><small>ADMIN</small></a><button className="admin-v2-collapse" aria-label={collapsed?'Expand sidebar':'Collapse sidebar'} onClick={()=>setCollapsed(value=>!value)}>{collapsed?<PanelLeftOpen size={17}/>:<PanelLeftClose size={17}/>}</button><button className="admin-v2-mobile-close" aria-label="Close navigation" onClick={()=>setMobileOpen(false)}><X size={18}/></button></div>
    <div className="admin-v2-quick-wrap"><button className="admin-v2-new" aria-expanded={quickOpen} onClick={()=>setQuickOpen(value=>!value)}><Plus size={17}/><span>Quick actions</span><ChevronDown size={14}/></button>{quickOpen&&<div className="admin-v2-quick-menu">{quickLinks.map(([path,label,Icon])=><a href={`/admin/${path}`} key={path}><Icon size={15}/>{label}</a>)}</div>}</div>
    <nav className="admin-v2-links" aria-label="Admin navigation">{nav}</nav>
    <div className="admin-v2-profile-wrap"><button className="admin-v2-profile" aria-expanded={profileOpen} onClick={()=>setProfileOpen(value=>!value)}><span className="admin-v2-avatar"><ShieldCheck size={17}/></span><span className="admin-v2-profile-copy"><b>Administrator</b><small>Platform admin</small></span><ChevronDown size={15}/></button>{profileOpen&&<div className="admin-v2-profile-menu"><a href="/">Public site</a><button onClick={()=>void logout()}><LogOut size={15}/>Sign out</button></div>}</div>
   </aside>
   <div className="admin-v2-workspace"><section className="admin-v2-main"><header className="admin-v2-toolbar"><button className="admin-v2-mobile-menu" aria-label="Open navigation" onClick={()=>setMobileOpen(true)}><Menu size={19}/></button><div className="admin-v2-toolbar-title"><small>PLATFORM CONTROL / {title.toUpperCase()}</small><h1>{title}</h1><p>{description}</p></div><div className="admin-v2-toolbar-actions"><button className="admin-v2-icon-button" aria-label="Open member management" title="Member management" onClick={()=>location.href='/admin/users'}><Search size={17}/></button><a className="admin-v2-icon-button admin-v2-notification" href="/admin/moderation" aria-label={`Open moderation, ${data.reports?.length||0} open reports`} title="Moderation"><Bell size={17}/>{Boolean(data.reports?.length)&&<i/>}</a><button className="admin-v2-avatar admin-v2-toolbar-avatar" aria-label="Administrator profile" onClick={()=>setToolbarProfileOpen(value=>!value)}><ShieldCheck size={17}/></button><button className="admin-v2-refresh" disabled={busy} onClick={()=>void load()}><RefreshCw size={15}/> Refresh</button></div>{toolbarProfileOpen&&<div className="admin-v2-toolbar-menu"><b>Administrator</b><small>Platform admin</small><button onClick={()=>void logout()}><LogOut size={15}/>Sign out</button></div>}</header>{error&&<div className="admin-v2-alert">{error}</div>}
 {section.startsWith('website-management/')&&<WebsiteManagement section={section}/>}
 {section==='story-moderation'&&<StoryModeration/>}
 {section==='dashboard'&&<><div className="admin-v2-metrics">{[['People online',stats.online],['Live video calls',stats.activeCalls],['Ready to connect',stats.availableRecipients],['Countries online',stats.countriesOnline]].map(([label,value],index)=><article key={String(label)}><span className={`admin-v2-metric-icon metric-${index}`}>{[<Users key="u" size={17}/>,<Video key="v" size={17}/>,<Activity key="a" size={17}/>,<Globe2 key="g" size={17}/>][index]}</span><small>{label}</small><b>{value??0}</b></article>)}</div><div className="admin-v2-grid"><Chart title="New accounts · last 7 days" values={data.userGrowth||[]} value="count"/><Chart title="Settled sales · last 7 days" values={data.revenueTrend||[]} value="amountCents" money/></div><div className="admin-v2-grid admin-v2-activity-grid"><section className="admin-v2-card"><div className="admin-v2-card-head"><h2>Recent members</h2><a className="admin-v2-text-link" href="/admin/users">View all <ArrowRight size={14}/></a></div><Table module="users" heads={['Member','Country','Joined']} rows={(data.users||[]).slice(0,5).map((u:any)=><tr key={u.id}><td><a className="admin-v2-user-link" href={`/admin/users/${u.id}`}>{u.displayName||u.email}</a></td><td>{u.profile?.country?countryName(u.profile.country):'—'}</td><td>{u.createdAt?new Date(u.createdAt).toLocaleDateString():'—'}</td></tr>)}/></section><section className="admin-v2-card"><div className="admin-v2-card-head"><h2>Safety queue</h2><a className="admin-v2-text-link" href="/admin/moderation">Review <ArrowRight size={14}/></a></div>{(data.reports||[]).length?(data.reports||[]).slice(0,5).map((report:any)=><div className="admin-v2-row" key={report.id}><div><b>{report.reported?.displayName||'Member report'}</b><small>{String(report.reason||'').replaceAll('_',' ')} · {new Date(report.createdAt).toLocaleDateString()}</small></div></div>):<p className="admin-v2-empty">No open safety reports.</p>}</section></div><section className="admin-v2-card"><h2>Quick access</h2><div className="admin-v2-quick">{quickLinks.map(([path,label,Icon])=><a key={path} href={`/admin/${path}`}><Icon size={15}/>{label}<ArrowRight size={14}/></a>)}</div></section></>}
 {(section==='users'||section==='creators'||section==='models')&&<><section className="admin-v2-card"><div className="admin-v2-card-head"><h2>{section==='creators'||section==='models'?'Creator accounts':'Accounts'} <small>({users.length} loaded)</small></h2></div><Table module={section==='creators'?'creators':'users'} heads={['Name','Email','Role','Country','Presence','Status','Actions']} rows={users.map((u:any)=><tr key={u.id}><td><a className="admin-v2-user-link" href={`/admin/users/${u.id}`}>{u.displayName}</a></td><td>{u.email}</td><td>{u.role==='ADMIN'?'Admin':`${u.role} · ${u.accountType||'USER'}${u.accountType==='CREATOR'?` (${u.creatorStatus||'PENDING'})`:''}`}</td><td>{u.profile?.country?countryName(u.profile.country):'—'}</td><td>{u.profile?.online?'Online':'Offline'}</td><td>{u.status}</td><td>{u.role!=='ADMIN'&&<>{section==='creators'&&u.creatorStatus!=='APPROVED'&&<button className="admin-v2-action" onClick={()=>void action({action:'creatorStatus',id:u.id,status:'APPROVED'})}>Approve</button>}{section==='creators'&&u.creatorStatus==='APPROVED'&&<button className="admin-v2-action" onClick={()=>void action({action:'creatorStatus',id:u.id,status:'REJECTED'})}>Revoke</button>}<button className="admin-v2-action" onClick={()=>action({action:'userStatus',id:u.id,status:u.status==='SUSPENDED'?'ACTIVE':'SUSPENDED'})}>{u.status==='SUSPENDED'?'Reactivate':'Suspend'}</button></>}</td></tr>)}/></section>{section==='users'&&<CreateUserForm refresh={load}/>}</>}
 {section.startsWith('users/')&&data.user&&<UserDetails data={data} refresh={load} action={actionWithoutResult}/> }
 {section==='gifts'&&<GiftsAdmin/>}
 {section==='matching'&&<div className="admin-v2-metrics">{[['Available women',stats.online],['Active calls',stats.activeCalls],['Calls recorded',stats.totalCalls]].map(([label,value])=><article key={String(label)}><small>{label}</small><b>{value??0}</b></article>)}</div>}
 {(section==='calls'||section==='video-sessions')&&<section className="admin-v2-card"><h2>Recent calls</h2><Table module="calls" heads={['Caller','Recipient','Status','Minutes','Coins','Action']} rows={(data.recentCalls||[]).map((c:any)=><tr key={c.id}><td>{c.caller?.displayName}</td><td>{c.recipient?.displayName}</td><td>{c.status}</td><td>{Math.floor((c.billableSeconds||0)/60)}</td><td>{c.coinsCharged}</td><td>{['ACTIVE','RINGING'].includes(c.status)&&<button className="admin-v2-action danger" onClick={()=>action({action:'terminateCall',id:c.id,reason:'Administrator ended call'})}>End call</button>}</td></tr>)}/></section>}
 {section==='wallets'&&<section className="admin-v2-card"><h2>Member wallets</h2><Table module="wallets" heads={['Member','Email','Coins','Available credits','Pending credits']} rows={(data.users||[]).map((u:any)=><tr key={u.id}><td><a className="admin-v2-user-link" href={`/admin/users/${u.id}`}>{u.displayName}</a></td><td>{u.email}</td><td>{u.wallet?.coinBalance??0}</td><td>{u.wallet?.availableCredits??0}</td><td>{u.wallet?.pendingCredits??0}</td></tr>)}/></section>}
 {section==='transactions'&&<section className="admin-v2-card"><h2>Financial ledger</h2><p className="admin-v2-note">Immutable coin and credit transactions, most recent 200 entries.</p><Table module="transactions" heads={['Date','Member','Type','Coins','Credits','Amount']} rows={(data.transactions||[]).map((t:any)=><tr key={t.id}><td>{new Date(t.createdAt).toLocaleString()}</td><td><a className="admin-v2-user-link" href={`/admin/users/${t.user?.id}`}>{t.user?.displayName||'—'}</a></td><td>{String(t.type).replaceAll('_',' ')}</td><td>{t.coins||0}</td><td>{t.credits||0}</td><td>{cash(t.amountCents||0)}</td></tr>)}/></section>}
 {section.startsWith('staff-management')&&<StaffManagement data={data} refresh={load} section={section}/>} {section==='support-center'&&<SupportCenter data={data} refresh={load}/>} {section==='coin-packages'&&<Packages data={data} refresh={load}/>} {section==='payments'&&<PaymentsAdmin data={data} action={actionWithoutResult}/> }

 {section==='payouts'&&<section className="admin-v2-card"><h2>Member withdrawals</h2><p className="admin-v2-note">Review requests and manually transfer payouts to the saved bank account. Stripe Connect remains available where configured.</p>{(data.withdrawals||[]).length?(data.withdrawals||[]).map((w:any)=>{const bank=w.user.payoutAccount?.bankDetails;return <div className="admin-v2-row admin-payout-row" key={w.id}><div><b>{w.user.displayName} · {cash(w.amountCents)}</b><small>{w.amountCredits} credits · {w.status} · {w.user.payoutAccount?.method==='MANUAL'?'Bank transfer':'Stripe Connect'}</small>{bank&&<small>Account holder: {bank.accountHolder} · {bank.bankName} · {bank.iban||bank.accountNumber}{bank.routingNumber?` · Routing ${bank.routingNumber}`:''}{bank.swiftCode?` · SWIFT ${bank.swiftCode}`:''} · {w.user.payoutAccount.country}</small>}</div>{w.status==='PENDING'&&<><button onClick={()=>action({action:'withdrawal',id:w.id,decision:'APPROVED'})}>Approve</button><button className="danger" onClick={()=>action({action:'withdrawal',id:w.id,decision:'REJECTED',reason:'Rejected by administrator'})}>Reject</button></>}{(w.status==='APPROVED'||w.status==='PROCESSING')&&w.user.payoutAccount?.method==='MANUAL'&&<button onClick={async()=>{const payoutRef=await dialog.prompt({title:'Complete bank transfer',description:'After sending the bank transfer, enter its bank reference to record completion.',confirmLabel:'Mark paid',inputLabel:'Bank transfer reference'});if(payoutRef?.trim())await action({action:'withdrawal',id:w.id,decision:'COMPLETED',payoutRef:payoutRef.trim()})}}>Mark paid</button>}</div>}) : <p className="admin-v2-empty">No withdrawal requests.</p>}</section>}
 {(section==='moderation'||section==='reports')&&<><div className="admin-v2-metrics">{[['Total reports',data.reportStats?.total??0],['Pending review',data.reportStats?.pending??0],['Urgent safety reports',data.reportStats?.urgent??0]].map(([label,value])=><article key={String(label)}><small>{label}</small><b>{value}</b></article>)}</div><section className="admin-v2-card"><h2>Safety reports · open and reviewing</h2>{(data.reports||[]).length?(data.reports||[]).map((r:any)=><div className="admin-v2-row" key={r.id}><div><b>{r.priority==='URGENT'?'URGENT · ':''}{r.reported.displayName} · {r.reason.replaceAll('_',' ')}</b><small>{r.status} · {r.severity} · {r.source} · Reported by {r.reporter.displayName} · {new Date(r.createdAt).toLocaleString()}</small><small>{r.details||'No additional explanation'}{r.callId?` · Call ${r.callId}`:''}{r.conversationId?` · Conversation ${r.conversationId}`:''}</small></div>{r.status==='OPEN'&&<button onClick={()=>action({action:'reportStatus',id:r.id,status:'REVIEWING'})}>Start review</button>}<button onClick={()=>action({action:'reportStatus',id:r.id,status:'RESOLVED'})}>Resolve</button><button onClick={()=>action({action:'reportStatus',id:r.id,status:'DISMISSED'})}>Dismiss</button>{r.reported.status==='ACTIVE'&&<button className="danger" onClick={()=>action({action:'userStatus',id:r.reported.id,status:'SUSPENDED'})}>Suspend account</button>}</div>):<p className="admin-v2-empty">No open safety reports.</p>}</section></>}
 {section==='analytics'&&<><div className="admin-v2-metrics">{[['Users',stats.total],['Women',stats.female],['Men',stats.male],['Minutes',stats.totalMinutes],['Sales',cash(stats.coinSalesCents)],['Commission',cash(stats.companyRevenueCents)]].map(([label,value])=><article key={String(label)}><small>{label}</small><b>{value??0}</b></article>)}</div><div className="admin-v2-grid"><Chart title="New accounts · last 7 days" values={data.userGrowth||[]} value="count"/><Chart title="Settled sales · last 7 days" values={data.revenueTrend||[]} value="amountCents" money/></div></>}
 {(section==='settings/general'||section==='settings/economy')&&<Settings data={data} economy={section.endsWith('economy')} onSave={action}/>}
 {section==='settings/appearance'&&<ThemeManager/>}{section==='settings/authentication'&&<AuthProviderSettings/>}
 {section==='settings/payments'&&<><section className="admin-v2-card payment-setup-guide"><h2>Quick payment setup</h2><p className="admin-v2-note">Paste each provider’s credentials below, save, then use its enable control. Credentials are encrypted on the server and are never shown again in the browser.</p><ol><li><b>Stripe coin checkout:</b> paste the secret key, publishable key, and webhook signing secret, then choose <b>Save &amp; enable Stripe Checkout</b>.</li><li><b>PayPal:</b> paste the Client ID, Client Secret, and Webhook ID, then save with PayPal enabled.</li><li><b>Stripe Link:</b> enable it after Stripe Checkout is active; it uses the existing Stripe credentials.</li><li><b>Adapty:</b> paste its server API key and webhook authorization value only if you use subscriptions.</li></ol></section><StripeSettings data={data}/><PaymentProviderSettings/></>}
 {section==='settings/sounds'&&<SoundManagement/>}
 {section==='audit-logs'&&<section className="admin-v2-card"><h2>Administrator audit log</h2>{(data.auditLogs||[]).length?(data.auditLogs||[]).map((l:any)=><div className="admin-v2-row" key={l.id}><div><b>{l.action.replaceAll('_',' ')}</b><small>{l.admin?.displayName} · {new Date(l.createdAt).toLocaleString()}</small></div></div>):<p className="admin-v2-empty">No administrator actions recorded.</p>}</section>}
 {!titles[section]&&<section className="admin-v2-card"><h2>Page not found</h2><a href="/admin/dashboard">Return to admin overview</a></section>}
 <footer><a href="/"><ArrowLeft size={14}/> Public site</a><span>Data loaded from Velora administration API</span></footer></section></div></div></main>
}
function Table({heads,rows,module=''}:{heads:string[];rows:any[];module?:string}){return <AdminDataTable heads={heads} rows={rows} module={module}/>}
function CreateUserForm({refresh}:{refresh:()=>Promise<void>}){
 const toast=useToast();const[name,setName]=useState(''),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[dateOfBirth,setDateOfBirth]=useState(''),[role,setRole]=useState<'MALE'|'FEMALE'>('FEMALE'),[accountType,setAccountType]=useState<'USER'|'CREATOR'>('USER'),[country,setCountry]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[verifyUrl,setVerifyUrl]=useState('');
 async function submit(event:React.FormEvent){event.preventDefault();setBusy(true);setError('');setVerifyUrl('');try{const response=await fetch('/api/admin/users',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({displayName:name,email,password,dateOfBirth,role,accountType,country})});const result=await readApiJson(response,'Could not create this account.') as {error?:string;emailSent?:boolean;devVerificationUrl?:string};if(!response.ok)throw new Error(result.error||'Could not create this account.');setName('');setEmail('');setPassword('');setDateOfBirth('');setCountry('');setVerifyUrl(result.devVerificationUrl||'');await refresh();toast.success('Member created',result.emailSent?'A verification email was sent.':'The account was created; email delivery is not configured.');}catch(cause){const message=cause instanceof Error?cause.message:'Could not create this account.';setError(message);toast.error('Unable to create member',message);}finally{setBusy(false)}}
 return <section className="admin-v2-card"><div className="admin-v2-card-head"><div><h2>Add a registered member</h2><p className="admin-v2-note">Members can use their account right away; email verification is available later in Profile Settings.</p></div></div><form className="admin-v2-form admin-create-user-form" onSubmit={submit}><label>Display name<input autoComplete="off" required minLength={2} maxLength={40} value={name} onChange={e=>setName(e.target.value)}/></label><label>Email<input type="email" autoComplete="off" required maxLength={160} value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Temporary password<input type="password" required minLength={8} maxLength={72} value={password} onChange={e=>setPassword(e.target.value)} autoComplete="new-password"/><small>At least 8 characters, with a letter and number.</small></label><label>Date of birth<DateOfBirthPicker value={dateOfBirth} max={new Date(Date.UTC(new Date().getUTCFullYear()-18,new Date().getUTCMonth(),new Date().getUTCDate())).toISOString().slice(0,10)} onChange={setDateOfBirth} required ariaLabel="Member date of birth" placeholder="Select date of birth"/></label><label>Account type<select value={accountType} onChange={e=>setAccountType(e.target.value as 'USER'|'CREATOR')}><option value="USER">User</option><option value="CREATOR">Creator (pending approval)</option></select></label><label>Gender<select value={role} onChange={e=>setRole(e.target.value as 'MALE'|'FEMALE')}><option value="FEMALE">Woman</option><option value="MALE">Man</option></select></label><label className="admin-create-country">Country<CountrySelect id="admin-new-user-country" value={country} onChange={setCountry} placeholder="Search country" required/></label><button disabled={busy||!country}>{busy?'Creating…':'Create member'}</button>{error&&<p className="admin-v2-alert" role="alert">{error}</p>}{verifyUrl&&<p className="admin-v2-note" role="status">Development verification link: <a href={verifyUrl}>{verifyUrl}</a></p>}</form></section>
}
function StaffManagement({data,refresh,section}:{data:Data;refresh:()=>Promise<void>;section:string}){const toast=useToast();const [search,setSearch]=useState(''),[busy,setBusy]=useState(false),[name,setName]=useState(''),[email,setEmail]=useState(''),[phone,setPhone]=useState(''),[department,setDepartment]=useState(''),[role,setRole]=useState('SUPPORT_AGENT'),[selected,setSelected]=useState<string[]>(['support']),[message,setMessage]=useState('');const roles=data.roles||['ADMIN','SUPPORT_MANAGER','SUPPORT_AGENT','FINANCE_MANAGER','MODERATOR'],perms=data.permissions||['dashboard','users','creators','support','payments','payouts','moderation','staff','settings'];const rows=(data.staff||[]).filter((s:any)=>`${s.user.displayName} ${s.user.email} ${s.department} ${s.staffRole}`.toLowerCase().includes(search.toLowerCase()));async function send(payload:any){setBusy(true);setMessage('');try{const r=await fetch('/api/admin/staff',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const j=await readApiJson(r,'Staff management action failed.') as any;if(!r.ok)throw new Error(j.error||'Action failed.');setMessage(j.developmentInvitationUrl?`Invitation email not configured. Development link: ${j.developmentInvitationUrl}`:'Staff update saved.');await refresh();toast.success('Staff management updated');return j}catch(e){toast.error('Staff update failed',e instanceof Error?e.message:'Try again.');return null}finally{setBusy(false)}}if(section==='staff-management/logs')return <section className="admin-v2-card"><h2>Activity Logs</h2><div className="table-scroll"><table><thead><tr><th>Administrator</th><th>Action</th><th>Target</th><th>Date</th></tr></thead><tbody>{(data.auditLogs||[]).map((log:any)=><tr key={log.id}><td>{log.admin?.displayName||log.admin?.email||'Administrator'}</td><td>{log.action}</td><td>{log.targetId||'—'}</td><td>{new Date(log.createdAt).toLocaleString()}</td></tr>)}</tbody></table></div>{!(data.auditLogs||[]).length&&<p className="admin-v2-empty">No staff actions have been recorded.</p>}</section>;if(section==='staff-management/roles')return <section className="admin-v2-card"><h2>Roles &amp; Permissions</h2><p className="admin-v2-note">Every permission is checked by the server for each protected admin API action.</p>{roles.map((r:string)=><article className="admin-v2-row" key={r}><div><b>{r.replaceAll('_',' ')}</b><small>{r==='SUPER_ADMIN'?'Full access, including staff and security settings.':r==='SUPPORT_AGENT'?'Support conversations and queue actions.':r==='SUPPORT_MANAGER'?'Support operations and agent management.':r==='FINANCE_MANAGER'?'Payments and payout operations.':r==='MODERATOR'?'User safety and story moderation.':'Configured access scopes.'}</small></div></article>)}<h3>Permission scopes</h3><p className="admin-v2-note">{perms.join(' · ')}</p></section>;return <div className="admin-staff-page"><section className="admin-v2-card"><div className="admin-v2-card-head"><div><h2>All Staff</h2><p className="admin-v2-note">Invitations expire after 72 hours. Staff set their own passwords using a single-use link.</p></div><label className="admin-staff-search"><Search size={15}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search staff"/></label></div>{message&&<p className="admin-v2-note" role="status">{message}</p>}<div className="table-scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Department</th><th>Role</th><th>Status</th><th>Last login</th><th>Actions</th></tr></thead><tbody>{rows.map((s:any)=><tr key={s.id}><td>{s.user.displayName}</td><td>{s.user.email}</td><td>{s.department||'—'}</td><td>{s.staffRole.replaceAll('_',' ')}</td><td>{s.user.status==='ACTIVE'&&s.enabled?'Active':s.invitationPending?'Invited':'Disabled'}</td><td>{s.lastLoginAt?new Date(s.lastLoginAt).toLocaleString():'Never'}</td><td className="admin-staff-actions"><button onClick={()=>{const next=window.prompt('Role ('+roles.join(', ')+')',s.staffRole);if(next&&roles.includes(next))void send({action:'edit',staffId:s.id,role:next,permissions:s.permissions,department:s.department,phone:s.phone})}}>Edit</button><button onClick={()=>void send({action:s.enabled?'disable':'reactivate',staffId:s.id})}>{s.enabled?'Disable':'Reactivate'}</button><button onClick={()=>void send({action:'revoke-sessions',staffId:s.id})}>Revoke sessions</button>{s.invitationPending&&<button onClick={()=>void send({action:'resend-invitation',staffId:s.id})}>Resend invite</button>}</td></tr>)}</tbody></table></div>{!rows.length&&<p className="admin-v2-empty">No staff accounts match this search.</p>}</section><section className="admin-v2-card admin-v2-form"><h2>Add Staff</h2><form onSubmit={async e=>{e.preventDefault();const result=await send({action:'create',name,email,phone,department,role,permissions:selected});if(result){setName('');setEmail('');setPhone('');setDepartment('')}}}><div className="admin-staff-form-grid"><label>Full name<input required minLength={2} maxLength={80} value={name} onChange={e=>setName(e.target.value)}/></label><label>Email<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label><label>Phone<input value={phone} onChange={e=>setPhone(e.target.value)} maxLength={40}/></label><label>Department<input value={department} onChange={e=>setDepartment(e.target.value)} maxLength={80}/></label><label>Role<select value={role} onChange={e=>setRole(e.target.value)}>{roles.map((r:string)=><option key={r} value={r}>{r.replaceAll('_',' ')}</option>)}</select></label></div><fieldset className="admin-staff-permissions"><legend>Roles &amp; Permissions</legend>{perms.map((p:string)=><label key={p}><input type="checkbox" checked={selected.includes(p)} onChange={e=>setSelected(v=>e.target.checked?[...v,p]:v.filter(x=>x!==p))}/>{p[0].toUpperCase()+p.slice(1)}</label>)}</fieldset><button disabled={busy}>{busy?'Sending invitation…':'Create staff account & send invitation'}</button></form><h3>Activity Logs</h3><p className="admin-v2-note">Staff changes, invitations, session revocations and role updates are recorded in the existing audit log.</p></section></div>}
function Chart({title,values,value,money=false}:{title:string;values:any[];value:string;money?:boolean}){const max=Math.max(1,...values.map(x=>Number(x[value]||0)));return <section className="admin-v2-card"><h2>{title}</h2><div className="admin-v2-chart">{values.length?values.map((v:any)=><div key={String(v.day)} title={money?cash(v[value]):String(v[value]||0)}><i style={{height:`${Math.max(5,Number(v[value]||0)*100/max)}%`}}/><small>{new Date(v.day).toLocaleDateString(undefined,{weekday:'short'})}</small></div>):<p>No chart data.</p>}</div></section>}
function SupportCenter({data,refresh}:{data:Data;refresh:()=>Promise<void>}){
 const toast=useToast();const [selected,setSelected]=useState('');const [question,setQuestion]=useState(''),[answer,setAnswer]=useState(''),[category,setCategory]=useState('General'),[reply,setReply]=useState(''),[note,setNote]=useState(''),[agentId,setAgentId]=useState(''),[announcement,setAnnouncement]=useState(''),[editingFaqId,setEditingFaqId]=useState(''),[busy,setBusy]=useState(false);
 const requests=data.requests||[];const active=requests.find((row:any)=>row.id===selected)||requests.find((row:any)=>['WAITING','ASSIGNED','IN_PROGRESS'].includes(row.status));
 useEffect(()=>{const timer=window.setInterval(()=>{if(document.visibilityState==='visible')void refresh()},5000);return()=>window.clearInterval(timer)},[refresh]);
 async function send(payload:any){setBusy(true);try{const response=await fetch('/api/admin/support',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const result=await readApiJson(response,'Support action failed.') as {error?:string;sent?:number};if(!response.ok)throw new Error(result.error||'Support action failed.');await refresh();toast.success('Support updated',payload.action==='announcement'?`Announcement sent to ${result.sent||0} accounts.`:'Support changes saved.');return true}catch(error){toast.error('Could not update support',error instanceof Error?error.message:'Try again.');return false}finally{setBusy(false)}}
 const metrics=data.metrics||{};return <div className="admin-v2-support"><div className="admin-v2-metrics">{[['Conversations',metrics.total],['Active chats',metrics.active],['Waiting',metrics.waiting],['Online agents',metrics.availableAgents],['First response',metrics.averageFirstResponseMinutes==null?'Unavailable':`${metrics.averageFirstResponseMinutes} min`],['Resolved',metrics.resolved],['Rating',metrics.averageRating==null?'—':`${Number(metrics.averageRating).toFixed(1)} / 5`]].map(([label,value])=><article key={String(label)}><small>{label}</small><b>{value??0}</b></article>)}</div>
 <section className="admin-v2-card"><h2>Live chats &amp; waiting queue</h2><p className="admin-v2-note">Accepting a chat assigns it atomically to you. Customer messages stay in Flirra Messages.</p><div className="admin-support-workspace"><aside>{requests.filter((row:any)=>['WAITING','ASSIGNED','IN_PROGRESS','RESOLVED','CLOSED'].includes(row.status)).map((row:any)=><button key={row.id} className={active?.id===row.id?'is-selected':''} onClick={()=>setSelected(row.id)}><b>{row.user.displayName}</b><small>{row.status} · {row.priority?'Priority':'Standard'}</small></button>)}</aside>{active?<div className="admin-support-thread"><header><b>{active.user.displayName}</b><small>{active.user.email} · {active.user.emailVerifiedAt?'Verified':'Unverified'} · {active.user.profile?.country||'Country unavailable'}</small></header><div className="admin-support-messages">{active.conversation.messages.map((message:any)=><article key={message.id} className={message.senderId===active.userId?'from-customer':''}><p>{message.body}</p><small>{new Date(message.createdAt).toLocaleString()}</small></article>)}</div>{active.status==='WAITING'&&<button disabled={busy} onClick={()=>void send({action:'claim',requestId:active.id})}>Accept Chat</button>}{active.assignedAgentId===data.currentAgentId&&<><form onSubmit={event=>{event.preventDefault();if(reply.trim())void send({action:'reply',requestId:active.id,body:reply}).then(ok=>ok&&setReply(''))}}><input value={reply} onChange={event=>setReply(event.target.value)} placeholder="Reply to customer"/><button disabled={busy||!reply.trim()}>Send</button></form><form onSubmit={event=>{event.preventDefault();if(note.trim())void send({action:'note',requestId:active.id,body:note}).then(ok=>ok&&setNote(''))}}><input value={note} onChange={event=>setNote(event.target.value)} placeholder="Internal note (customer cannot see this)"/><button disabled={busy||!note.trim()}>Add note</button></form><div className="admin-support-notes">{active.notes.map((entry:any)=><small key={entry.id}>Internal · {entry.agent.displayName}: {entry.body}</small>)}</div><button disabled={busy} onClick={()=>void send({action:'resolve',requestId:active.id})}>Mark Resolved</button></>}{active.status==='RESOLVED'&&<button disabled={busy} onClick={()=>void send({action:'reopen',requestId:active.id})}>Reopen Conversation</button>}</div>:<p className="admin-v2-empty">No support request selected.</p>}</div></section>
 <div className="admin-v2-grid"><section className="admin-v2-card"><h2>Support agents</h2><div className="admin-support-agent-add"><select value={agentId} onChange={event=>setAgentId(event.target.value)}><option value="">Choose an administrator</option>{(data.admins||[]).map((admin:any)=><option key={admin.id} value={admin.id}>{admin.displayName} · {admin.email}</option>)}</select><button disabled={busy||!agentId} onClick={()=>void send({action:'agent-save',userId:agentId,availability:'OFFLINE',maxChats:3})}>Add agent</button></div>{(data.agents||[]).map((agent:any)=><div className="admin-v2-row" key={agent.id}><div><b>{agent.user.displayName}</b><small>{agent.availability} · {agent.maxChats} simultaneous chats</small></div><select value={agent.availability} onChange={event=>void send({action:'agent-save',userId:agent.userId,availability:event.target.value,maxChats:agent.maxChats})}><option>ONLINE</option><option>BUSY</option><option>AWAY</option><option>OFFLINE</option></select><button className="danger" onClick={()=>void send({action:'agent-remove',userId:agent.userId})}>Remove</button></div>)}</section><section className="admin-v2-card"><h2>FAQ Management</h2><form className="admin-v2-form" onSubmit={event=>{event.preventDefault();void send({action:'faq-save',...(editingFaqId?{id:editingFaqId}:{}) ,question,answer,category,sortOrder:editingFaqId?(data.faqs||[]).find((item:any)=>item.id===editingFaqId)?.sortOrder||(data.faqs||[]).length:(data.faqs||[]).length}).then(ok=>{if(ok){setQuestion('');setAnswer('');setEditingFaqId('')}})}}><label>Question<input value={question} onChange={event=>setQuestion(event.target.value)} required/></label><label>Category<input value={category} onChange={event=>setCategory(event.target.value)}/></label><label>Approved answer<textarea value={answer} onChange={event=>setAnswer(event.target.value)} required/></label><div className="admin-v2-form-actions"><button disabled={busy}>{editingFaqId?'Save answer':'Add FAQ'}</button>{editingFaqId&&<button type="button" onClick={()=>{setEditingFaqId('');setQuestion('');setAnswer('');setCategory('General')}}>Cancel edit</button>}</div></form>{(data.faqs||[]).map((faq:any)=><div className="admin-v2-row" key={faq.id}><div><b>{faq.question}</b><small>{faq.category} · {faq.enabled?'Enabled':'Disabled'}{faq.escalate?' · Escalates to agent':''}</small></div><button onClick={()=>{setEditingFaqId(faq.id);setQuestion(faq.question);setAnswer(faq.answer);setCategory(faq.category);window.scrollTo({top:0,behavior:'smooth'})}}>Edit answer</button><button onClick={()=>void send({action:'faq-save',id:faq.id,question:faq.question,answer:faq.answer,category:faq.category,keywords:Array.isArray(faq.keywords)?faq.keywords:[],followUps:Array.isArray(faq.followUps)?faq.followUps:[],sortOrder:faq.sortOrder,enabled:!faq.enabled,escalate:faq.escalate})}>{faq.enabled?'Disable':'Enable'}</button><button className="danger" onClick={()=>void send({action:'faq-delete',id:faq.id})}>Delete</button></div>)}</section></div>
 <section className="admin-v2-card"><h2>Support settings &amp; announcements</h2><p className="admin-v2-note">Team welcome messages apply to new accounts. Announcements are sent to each existing Flirra Team conversation.</p><textarea value={announcement} onChange={event=>setAnnouncement(event.target.value)} placeholder="Write an announcement for all members"/><button disabled={busy||!announcement.trim()} onClick={()=>void send({action:'announcement',announcement}).then(ok=>ok&&setAnnouncement(''))}>Send announcement</button><label className="admin-support-setting"><input type="checkbox" checked={data.settings?.liveEnabled!==false} onChange={event=>void send({action:'settings',teamWelcome:data.settings?.teamWelcome||'',liveEnabled:event.target.checked,automaticAssignment:data.settings?.automaticAssignment!==false,queueCapacity:data.settings?.queueCapacity||500,operatingHours:data.settings?.operatingHours||''})}/> Live support enabled</label><label>Welcome message for new Team conversations<textarea defaultValue={data.settings?.teamWelcome||''} onBlur={event=>{if(event.target.value!== (data.settings?.teamWelcome||''))void send({action:'settings',teamWelcome:event.target.value,liveEnabled:data.settings?.liveEnabled!==false,automaticAssignment:data.settings?.automaticAssignment!==false,queueCapacity:data.settings?.queueCapacity||500,operatingHours:data.settings?.operatingHours||''})}}/></label></section></div>
}

function Packages({data,refresh}:{data:Data;refresh:()=>Promise<void>}){
 const dialog=useDialog();
 const toast=useToast();
 const empty={name:'',description:'',coins:'',price:'',currency:'USD',bonusCoins:'',cardColor:'lilac',imageUrl:'',popular:false,active:true,sortOrder:''};
 const [form,setForm]=useState<any>(empty),[editing,setEditing]=useState<string|null>(null),[busy,setBusy]=useState(false),[uploading,setUploading]=useState(false),[error,setError]=useState('');
 async function send(payload:any){setBusy(true);setError('');try{const r=await fetch('/api/admin',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)});const j=await readApiJson(r,'Administrator request failed.');if(!r.ok)throw new Error(j.error);await refresh();toast.success('Coin package updated','The public and wallet package lists now reflect your changes.');return true}catch(e){const message=e instanceof Error?e.message:'Could not save package';setError(message);toast.error('Could not update package',message);return false}finally{setBusy(false)}}
 async function save(e:FormEvent){e.preventDefault();const price=Number(form.price),coins=Number(form.coins),bonusCoins=Number(form.bonusCoins),sortOrder=Number(form.sortOrder);if(!form.coins||!Number.isInteger(coins)||coins<1){setError('Enter the coin quantity.');return}if(!form.price||!Number.isFinite(price)||price<0.5||price>10000){setError('Enter a price from $0.50 to $10,000.00.');return}if(form.bonusCoins===''||!Number.isInteger(bonusCoins)||bonusCoins<0){setError('Enter a bonus coin amount, including 0 if there is no bonus.');return}if(form.sortOrder===''||!Number.isInteger(sortOrder)||sortOrder<0){setError('Enter a display order.');return}if(await send({action:'package',...(editing?{id:editing}:{}),...form,price:undefined,coins,priceCents:Math.round(price*100),bonusCoins,sortOrder})){setForm(empty);setEditing(null)}}
 async function uploadArtwork(file?:File){if(!file)return;setUploading(true);setError('');try{const body=new FormData();body.set('file',file);body.set('altText',`${form.name||'Coin package'} artwork`);const response=await fetch('/api/admin/cms/media',{method:'POST',body});const result=await readApiJson(response,'Could not upload package artwork.') as {media?:{url?:string};error?:string};if(!response.ok||!result.media?.url)throw new Error(result.error||'Could not upload package artwork.');setForm((current:any)=>({...current,imageUrl:result.media!.url}));toast.success('Artwork uploaded','Save the package to publish the new image.')}catch(cause){const message=cause instanceof Error?cause.message:'Could not upload package artwork.';setError(message);toast.error('Artwork upload failed',message)}finally{setUploading(false)}}
 const packages=[...(data.packages||[])].sort((x:any,y:any)=>x.sortOrder-y.sortOrder);
 const coinsPerMinute=Number(data.settings?.coinsPerMinute||0);
 return <section className="admin-v2-card"><div className="admin-v2-card-head"><div><h2>Coin packages</h2><p className="admin-v2-note">Active packages appear in the wallet shop. Payment prices are taken from this saved catalog.</p></div></div>{error&&<p className="admin-v2-alert" role="alert">{error}</p>}
 {packages.map((pkg:any,index:number)=>{
  const edit=()=>{setEditing(pkg.id);setForm({name:pkg.name,description:pkg.description||'',coins:String(pkg.coins),price:(pkg.priceCents/100).toFixed(2),currency:pkg.currency||'USD',bonusCoins:String(pkg.bonusCoins),cardColor:pkg.cardColor||'lilac',imageUrl:pkg.imageUrl||'',popular:Boolean(pkg.popular),active:Boolean(pkg.active),sortOrder:String(pkg.sortOrder)})};
  return <div className="admin-v2-row" key={pkg.id}><div><b>{pkg.name}{pkg.popular?' · Most popular':''}</b><small>{pkg.coins.toLocaleString()} coins {pkg.bonusCoins?`+ ${pkg.bonusCoins} bonus`:''} · {coinsPerMinute?Math.floor((pkg.coins+(pkg.bonusCoins||0))/coinsPerMinute):'—'} call minutes · {(pkg.priceCents/100).toLocaleString(undefined,{style:'currency',currency:pkg.currency||'USD'})} · {pkg.active?'Active':'Paused'}</small></div><div className="admin-package-actions"><button disabled={busy||index===0} onClick={()=>void send({action:'packageReorder',id:pkg.id,direction:'up'})}>↑</button><button disabled={busy||index===packages.length-1} onClick={()=>void send({action:'packageReorder',id:pkg.id,direction:'down'})}>↓</button><button disabled={busy} onClick={edit}>Edit</button><button disabled={busy} onClick={()=>void send({action:'package',...pkg,active:!pkg.active})}>{pkg.active?'Disable':'Enable'}</button><button className="danger" disabled={busy} onClick={async()=>{if(await dialog.confirm({title:`Delete ${pkg.name}?`,description:'Packages with payment history are archived automatically so past transactions remain intact.',confirmLabel:'Delete package',danger:true})){void send({action:'packageDelete',id:pkg.id})}}}>Delete</button></div></div>
 })}
 <form className="admin-v2-form admin-package-form" onSubmit={save}><h3>{editing?'Edit package':'Add package'}</h3><label>Package name<input required minLength={2} maxLength={60} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label>Description<input maxLength={240} value={form.description} onChange={e=>setForm({...form,description:e.target.value})}/></label><label>Coins<input type="number" min="1" required value={form.coins} onChange={e=>setForm({...form,coins:e.target.value})}/></label><label>Price<input type="number" min="0.50" max="10000" step="0.01" inputMode="decimal" required value={form.price} onChange={e=>setForm({...form,price:e.target.value})}/></label><label>Currency<input required maxLength={3} value={form.currency} onChange={e=>setForm({...form,currency:e.target.value.toUpperCase()})}/></label><label>Bonus coins<input type="number" min="0" required value={form.bonusCoins} onChange={e=>setForm({...form,bonusCoins:e.target.value})}/></label><label>Display order<input type="number" min="0" required value={form.sortOrder} onChange={e=>setForm({...form,sortOrder:e.target.value})}/></label><label>Status<select value={String(form.active)} onChange={e=>setForm({...form,active:e.target.value==='true'})}><option value="true">Active</option><option value="false">Paused</option></select></label><label className="admin-package-artwork-field">Package image<div><input type="url" value={form.imageUrl} placeholder="Image URL (optional)" onChange={e=>setForm({...form,imageUrl:e.target.value})}/><label className="admin-file-button"><Image size={14}/>{uploading?'Uploading…':'Upload image'}<input type="file" accept="image/jpeg,image/png,image/webp,image/gif" disabled={uploading||busy} onChange={e=>{void uploadArtwork(e.currentTarget.files?.[0]);e.currentTarget.value=''}}/></label></div></label>{form.imageUrl&&<div className="admin-package-artwork-preview"><img src={form.imageUrl} alt="Coin package preview"/><button type="button" className="admin-package-remove-art" onClick={()=>setForm({...form,imageUrl:''})}>Remove image</button></div>}<div className="admin-package-actions"><button disabled={busy||uploading}>{busy?'Saving…':editing?'Save package':'Add package'}</button><button type="button" onClick={()=>{setEditing(null);setForm(empty);setError('')}} disabled={busy||uploading}>Cancel{editing?' edit':''}</button></div></form></section>
}
