 const toast=useToast();useEffect(()=>setSettings(data.settings),[data.settings]);if(!settings)return null;
 const keys=economy?['coinsPerMinute','womanShareBps','creditValueCents','minWithdrawalCredits','guestWelcomeCoins','registeredWelcomeCoins','dailyRewardCoins','promoRewardCoins','rewardExpirationDays','maxPromoCoins']:['siteName','supportEmail','emailFrom','callRingSeconds','maintenanceMode'];
 const labels:Record<string,string>={siteName:'Site name',supportEmail:'Support email',emailFrom:'Email sender',callRingSeconds:'Call ring timeout (seconds)',maintenanceMode:'Maintenance mode',coinsPerMinute:'Coins per minute',womanShareBps:'Recipient share (%)',creditValueCents:'Value per credit ($)',minWithdrawalCredits:'Minimum withdrawal (credits)',guestWelcomeCoins:'Guest welcome coins',registeredWelcomeCoins:'Registered welcome coins',dailyRewardCoins:'Daily reward coins',promoRewardCoins:'Promo reward coins',rewardExpirationDays:'Reward expiration (days)',maxPromoCoins:'Maximum promotional coins'};
 async function uploadLogo(file?:File){if(!file)return;setUploading(true);setUploadError('');try{const body=new FormData();body.set('file',file);body.set('altText',`${settings.siteName} logo`);const response=await fetch('/api/admin/cms/media',{method:'POST',body});const result=await readApiJson(response,'Could not upload the logo.') as {media?:{url?:string};error?:string};if(!response.ok||!result.media?.url)throw new Error(result.error||'Could not upload the logo.');setSettings({...settings,logoUrl:result.media.url});setSaved(false);toast.success('Logo uploaded','Save general settings to publish the new logo.')}catch(error){setUploadError(error instanceof Error?error.message:'Could not upload the logo.')}finally{setUploading(false)}}
