 const numericKeys=['callRingSeconds','coinsPerMinute','womanShareBps','creditValueCents','minWithdrawalCredits','guestWelcomeCoins','registeredWelcomeCoins','dailyRewardCoins','promoRewardCoins','rewardExpirationDays','maxPromoCoins'];
