 const [secretKey,setSecretKey]=useState(''),[webhookSecret,setWebhookSecret]=useState(''),[connectSecret,setConnectSecret]=useState(''),[publishableKey,setPublishableKey]=useState('');
 const [paymentsEnabled,setPaymentsEnabled]=useState(Boolean(data.paymentsEnabled)),[connectEnabled,setConnectEnabled]=useState(Boolean(data.connectEnabled)),[saving,setSaving]=useState(false),[testing,setTesting]=useState(false),[saved,setSaved]=useState(false),[error,setError]=useState(''),[connectionStatus,setConnectionStatus]=useState(''),[runtimeConfigError,setRuntimeConfigError]=useState(data.stripeConfigurationError||''),[showSecrets,setShowSecrets]=useState(false);
 useEffect(()=>{setPaymentsEnabled(Boolean(data.paymentsEnabled));setConnectEnabled(Boolean(data.connectEnabled));setRuntimeConfigError(data.stripeConfigurationError||'')},[data.paymentsEnabled,data.connectEnabled,data.stripeConfigurationError]);
 const accountIdError=accountId.trim()&&!/^acct_[A-Za-z0-9]+$/.test(accountId.trim())?(accountId.trim().startsWith('org_')?'Use the platform account ID beginning acct_. An org_ ID is not an account context.':'Use an account ID beginning acct_, or leave this field empty for an account-level key.'):'';
 async function save(enableCheckout=paymentsEnabled){if(accountIdError){setError(accountIdError);return}setSaving(true);setError('');setSaved(false);try{const r=await fetch('/api/admin',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({action:'stripeSettings',accountId:accountId.trim(),...(secretKey?{secretKey}:{}),...(webhookSecret?{webhookSecret}:{}),...(connectSecret?{connectSecret}:{}),...(publishableKey?{publishableKey}:{}),paymentsEnabled:enableCheckout,connectEnabled})});const j=await readApiJson(r,'Could not save Stripe settings.') as {error?:string;paymentsEnabled?:boolean;connectEnabled?:boolean;stripeConfigurationError?:string};if(!r.ok)throw new Error(j.error||'Could not save Stripe settings.');setPaymentsEnabled(Boolean(j.paymentsEnabled));setConnectEnabled(Boolean(j.connectEnabled));setRuntimeConfigError(j.stripeConfigurationError||'');setSecretKey('');setWebhookSecret('');setConnectSecret('');setPublishableKey('');setSaved(true);window.dispatchEvent(new CustomEvent('velora-admin-refresh'))}catch(e){setError(e instanceof Error?e.message:'Could not save Stripe settings.')}finally{setSaving(false)}}
